# Basic try/except
try:
    number = int(input('Enter a number: '))
    result = 100 / number
    print(f'Result: {result}')
except ValueError:
    print('That was not a valid number!')
except ZeroDivisionError:
    print('Cannot divide by zero!')

# Catching multiple exceptions in one handler
try:
    risky_operation()
except (TypeError, AttributeError) as e:
    print(f'Type/attribute problem: {e}')

# Catch ANY exception (use sparingly!)
try:
    risky_operation()
except Exception as e:
    print(f'Something went wrong: {e}')
    # log it, then re-raise or handle

# Accessing exception info
try:
    x = int('abc')
except ValueError as e:
    print(f'Error: {e}')          # invalid literal for int()...
    print(type(e).__name__)       # 'ValueError'

