# Raise a built-in exception
def set_age(age):
    if not isinstance(age, int):
        raise TypeError(f'Age must be an integer, got {type(age).__name__}')
    if age < 0 or age > 150:
        raise ValueError(f'Age must be between 0 and 150, got {age}')
    return age

# Raise from another exception (preserve context)
def load_config(filepath):
    try:
        with open(filepath) as f:
            return json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f'Invalid config file: {filepath}') from e

# Re-raise the current exception (add logging then re-raise)
def process(data):
    try:
        result = complex_operation(data)
    except Exception as e:
        logger.error(f'Failed processing: {e}')
        raise  # bare raise re-raises the SAME exception

