# Base custom exception for your application
class AppError(Exception):
    """Base class for all application errors."""
    pass

# Specific error types
class ValidationError(AppError):
    """Raised when input fails validation."""
    def __init__(self, field, message):
        self.field = field
        self.message = message
        super().__init__(f'Validation error on {field}: {message}')

class NotFoundError(AppError):
    """Raised when a requested resource does not exist."""
    def __init__(self, resource, identifier):
        self.resource = resource
        self.identifier = identifier
        super().__init__(f'{resource} not found: {identifier}')

# Using custom exceptions
def get_user(user_id, users_db):
    if not isinstance(user_id, int) or user_id <= 0:
        raise ValidationError('user_id', 'must be a positive integer')
    user = users_db.get(user_id)
    if user is None:
        raise NotFoundError('User', user_id)
    return user

# Catching custom exceptions
try:
    user = get_user(-1, {})
except ValidationError as e:
    print(f'Bad input for field {e.field}: {e.message}')
except NotFoundError as e:
    print(f'{e.resource} #{e.identifier} does not exist')
except AppError as e:
    print(f'Application error: {e}')  # catch-all for app errors
